const fzPeriods = n => { const out = []; let y = +PROC_TODAY.slice(0, 4), m = +PROC_TODAY.slice(5, 7); for (let i = 0; i < n; i++) { m--; if (m < 1) { m = 12; y--; } out.push(`${y}-${String(m).padStart(2, '0')}`); } return out; };
