/* ---------- tickets ---------- */
FZ_ACT.frnTkForm = () => { const V = fzVisible(fzD()); if (!fzCan('Add') || !V.length) return; modal('Raise support ticket', `<div class="form-grid">${pcFld('Franchisee', pcSel('tk_f', V.map(x => [x.id, x.name]), App.ui.frnF || ''))}${pcFld('Category', pcSel('tk_c', ['Admissions', 'Fees and billing', 'Academics', 'ERP / technology', 'Training', 'Compliance', 'Marketing and brand', 'Other'], 'Academics'))}${pcFld('Priority', pcSel('tk_p', ['High', 'Medium', 'Low'], 'Medium'))}</div>` + pcFld('Subject', '<input id="tk_s">') + pcFld('Details', '<textarea id="tk_d" rows="3"></textarea>'), `<button class="btn primary" data-act="frnTkOk">Raise</button><button class="btn" data-act="closeModal">Cancel</button>`, true); };
FZ_ACT.frnTkOk = async () => { const d = Store.clone(fzD()), s = (v('tk_s') || '').trim(), det = (v('tk_d') || '').trim(), prio = v('tk_p'); if (!v('tk_f') || !s || det.length < 10) return toast('Enter the subject and describe the problem (at least 10 characters).', 'bad'); const at = nowIso(), due = new Date(Date.now() + FZ_SLA[prio] * 3600000).toISOString(); d.tk.push({ id: 'TK' + Date.now().toString(36), no: 'FT-' + String(d.tk.length + 1).padStart(5, '0'), fid: v('tk_f'), cat: v('tk_c'), prio, subject: s, state: 'Open', level: 1, due, at, by: App.user.name, msgs: [{ by: App.user.name, at, text: det }] }); fzLog(d, v('tk_f'), `Ticket raised: ${s}`, { new: prio }, ''); await fzSave(d); closeModal(); };
FZ_ACT.frnTkOpen = t => {
  const k = fzD().tk.find(x => x.id === t.dataset.k); if (!k) return; const me = (App.user || {}).name, closed = ['Resolved', 'Closed'].includes(k.state);
  modal(`${k.no} · ${k.subject}`, `<p class="small">${esc((fzD().fr.find(x => x.id === k.fid) || {}).name)} · ${k.cat} · ${k.prio} · Level ${k.level} · ${k.state}${fzTkLate(k) ? ' · <b style="color:#c0392b">response target missed</b>' : ''}</p><div style="max-height:220px;overflow:auto">${k.msgs.map(m => `<p><b>${esc(m.by)}</b> <span class="muted small">${tsLabel(m.at)}</span><br>${esc(m.text)}</p>`).join('')}</div>${closed ? '' : pcFld('Reply', '<textarea id="tm_t" rows="2"></textarea>')}`, (closed ? (fzCan('Edit') && k.state === 'Resolved' ? `<button class="btn primary" data-act="frnTkClose" data-k="${k.id}">Close ticket</button><button class="btn" data-act="frnTkReopen" data-k="${k.id}">Reopen</button>` : '') : `<button class="btn primary" data-act="frnTkReply" data-k="${k.id}">Send reply</button>${fzCan('Edit') ? `<button class="btn" data-act="frnTkResolve" data-k="${k.id}">Mark resolved</button>` : ''}${fzTkLate(k) && fzCan('Edit') && k.level < 3 ? `<button class="btn" data-act="frnTkEsc" data-k="${k.id}">Escalate</button>` : ''}`) + '<button class="btn" data-act="closeModal">Close window</button>', true);
};
FZ_ACT.frnTkReply = async t => { const tx = (v('tm_t') || '').trim(); if (!tx) return toast('Write a reply.', 'bad'); const d = Store.clone(fzD()), k = d.tk.find(x => x.id === t.dataset.k); k.msgs.push({ by: App.user.name, at: nowIso(), text: tx }); if (k.state === 'Open') k.state = 'In progress'; fzLog(d, k.fid, `Ticket reply: ${k.no}`, {}, ''); await fzSave(d); closeModal(); };
FZ_ACT.frnTkResolve = t => { const k = fzD().tk.find(x => x.id === t.dataset.k); if (!k) return; closeModal(); askReason('Resolve ticket', `${k.no}. Describe the resolution.`, async reason => { if (reason.trim().length < 10) return toast('Describe the resolution (at least 10 characters).', 'bad'); const d = Store.clone(fzD()), x = d.tk.find(y => y.id === k.id); x.state = 'Resolved'; x.msgs.push({ by: App.user.name, at: nowIso(), text: 'Resolved: ' + reason }); x.resBy = App.user.name; fzLog(d, x.fid, `Ticket resolved: ${x.no}`, { old: k.state, new: 'Resolved' }, reason); await fzSave(d); rerender(); }); };
FZ_ACT.frnTkClose = async t => { const d = Store.clone(fzD()), k = d.tk.find(x => x.id === t.dataset.k); if (k.resBy === App.user.name) { return toast('You resolved this ticket, so someone else must close it.', 'bad'); } k.state = 'Closed'; fzLog(d, k.fid, `Ticket closed: ${k.no}`, { old: 'Resolved', new: 'Closed' }, ''); await fzSave(d); closeModal(); };
FZ_ACT.frnTkReopen = t => { const k = fzD().tk.find(x => x.id === t.dataset.k); closeModal(); askReason('Reopen ticket', k.no, async reason => { if (!reason.trim()) return toast('A reason is required.', 'bad'); const d = Store.clone(fzD()), x = d.tk.find(y => y.id === k.id); x.state = 'Open'; x.due = new Date(Date.now() + FZ_SLA[x.prio] * 3600000).toISOString(); fzLog(d, x.fid, `Ticket reopened: ${x.no}`, { old: 'Resolved', new: 'Open' }, reason); await fzSave(d); rerender(); }); };
FZ_ACT.frnTkEsc = t => { const k = fzD().tk.find(x => x.id === t.dataset.k); if (!k || !fzTkLate(k)) return; closeModal(); askReason('Escalate ticket', `${k.no} moves to level ${k.level + 1} with a new response target.`, async reason => { if (!reason.trim()) return toast('A reason is required.', 'bad'); const d = Store.clone(fzD()), x = d.tk.find(y => y.id === k.id); x.level++; x.due = new Date(Date.now() + FZ_SLA[x.prio] * 1800000).toISOString(); x.msgs.push({ by: App.user.name, at: nowIso(), text: 'Escalated: ' + reason }); fzLog(d, x.fid, `Ticket escalated: ${x.no}`, { old: 'L' + k.level, new: 'L' + x.level }, reason); await fzSave(d); rerender(); }); };
/* ---------- observations ---------- */
FZ_ACT.frnObsForm = () => { const V = fzVisible(fzD()); if (!fzCan('Add') || !V.length) return; modal('Record audit observation', `<div class="form-grid">${pcFld('Franchisee', pcSel('ob_f', V.map(x => [x.id, x.name]), App.ui.frnF || ''))}${pcFld('Visit date', `<input id="ob_d" type="date" value="${PROC_TODAY}" max="${PROC_TODAY}">`)}${pcFld('Severity', pcSel('ob_s', ['High', 'Medium', 'Low'], 'Medium'))}${pcFld('Response due', `<input id="ob_u" type="date" value="${pcAddDays(PROC_TODAY, 14)}">`)}</div>${pcFld('Observation', '<textarea id="ob_t" rows="3"></textarea>')}${pcFld('Evidence – file name and where kept', '<input id="ob_e">')}`, `<button class="btn primary" data-act="frnObsOk">Record</button><button class="btn" data-act="closeModal">Cancel</button>`, true); };
FZ_ACT.frnObsOk = async () => { const o = { fid: v('ob_f'), date: v('ob_d'), sev: v('ob_s'), due: v('ob_u'), text: (v('ob_t') || '').trim(), file: (v('ob_e') || '').trim() }; if (!o.fid || o.text.length < 10) return toast('Describe the observation (at least 10 characters).', 'bad'); if (!o.date || o.date > PROC_TODAY) return toast('The visit date cannot be in the future.', 'bad'); if (!o.due || o.due < o.date) return toast('The response date cannot be before the visit.', 'bad'); const d = Store.clone(fzD()); d.obs.push(Object.assign(o, { id: 'OB' + Date.now().toString(36), state: 'Open', by: App.user.name })); fzLog(d, o.fid, `Observation recorded (${o.sev})`, { new: o.text.slice(0, 80) }, ''); await fzSave(d); closeModal(); };
FZ_ACT.frnObsResp = t => modal('Franchise response', pcFld('Response and corrective action', '<textarea id="or_t" rows="3"></textarea>') + pcFld('Evidence – file name and where kept', '<input id="or_f">'), `<button class="btn primary" data-act="frnObsRespOk" data-k="${t.dataset.k}">Submit</button><button class="btn" data-act="closeModal">Cancel</button>`);
FZ_ACT.frnObsRespOk = async t => { const tx = (v('or_t') || '').trim(); if (tx.length < 10) return toast('Describe the corrective action.', 'bad'); const d = Store.clone(fzD()), o = d.obs.find(x => x.id === t.dataset.k); o.resp = { text: tx, file: (v('or_f') || '').trim(), by: App.user.name, at: nowIso() }; o.state = 'Responded'; fzLog(d, o.fid, 'Observation response recorded', { old: 'Open', new: 'Responded' }, tx); await fzSave(d); closeModal(); };
FZ_ACT.frnObsClose = t => { const o = fzD().obs.find(x => x.id === t.dataset.k); if (!o || !fzCan('Approve')) return; if (o.resp.by === App.user.name) return toast('You recorded the response, so someone else must close it.', 'bad'); askReason('Close observation', o.text.slice(0, 80), async reason => { const d = Store.clone(fzD()), x = d.obs.find(y => y.id === o.id); x.state = 'Closed'; x.closeBy = App.user.name; x.closeAt = nowIso(); fzLog(d, x.fid, 'Observation closed', { old: 'Responded', new: 'Closed' }, reason); await fzSave(d); rerender(); }); };
FZ_ACT.frnObsReopen = t => { const o = fzD().obs.find(x => x.id === t.dataset.k); if (!o) return; askReason('Reject response', 'Say why the response is not enough.', async reason => { if (!reason.trim()) return toast('A reason is required.', 'bad'); const d = Store.clone(fzD()), x = d.obs.find(y => y.id === o.id); x.state = 'Open'; fzLog(d, x.fid, 'Observation response rejected', { old: 'Responded', new: 'Open' }, reason); await fzSave(d); rerender(); }); };
FZ_ACT.frnObsEsc = t => { const o = fzD().obs.find(x => x.id === t.dataset.k); if (!o) return; askReason('Escalate overdue observation', 'It is flagged to Corporate management.', async reason => { if (!reason.trim()) return toast('A reason is required.', 'bad'); const d = Store.clone(fzD()), x = d.obs.find(y => y.id === o.id); x.esc = { by: App.user.name, at: nowIso(), reason }; fzLog(d, x.fid, 'Observation escalated', {}, reason); await fzSave(d); rerender(); }); };
/* ---------- documents ---------- */
FZ_ACT.frnDocForm = () => { if (!fzCan('Add')) return; modal('Add document', `<div class="form-grid">${pcFld('Type', pcSel('dc_t', FZ_DOCS, FZ_DOCS[0]))}${pcFld('Expiry date (blank if none)', '<input id="dc_e" type="date">')}</div>${pcFld('Title', '<input id="dc_n">')}${pcFld('File name and where the original is kept', '<input id="dc_f">')}`, `<button class="btn primary" data-act="frnDocOk">Save</button><button class="btn" data-act="closeModal">Cancel</button>`); };
FZ_ACT.frnDocOk = async () => { const fid = App.ui.frnF, d0 = fzD(), x = { type: v('dc_t'), title: (v('dc_n') || '').trim(), file: (v('dc_f') || '').trim(), exp: v('dc_e') }; if (!x.title || !x.file) return toast('Enter the title and the file reference.', 'bad'); if (d0.docs.some(y => y.fid === fid && y.title.toLowerCase() === x.title.toLowerCase())) return toast('A document with this title is already recorded.', 'bad'); const d = Store.clone(d0); d.docs.push(Object.assign(x, { id: 'DC' + Date.now().toString(36), fid, by: App.user.name })); fzLog(d, fid, `Document added: ${x.title}`, { new: x.type }, ''); await fzSave(d); closeModal(); };
/* ---------- billing ---------- */
FZ_ACT.frnMode = e => { const fid = App.ui.frnF, val = e.value || (e.target && e.target.value); if (!fzCan('Edit') || !fid) return; askReason('Change who bills', `Billing mode: ${val}.`, async reason => { const d = Store.clone(fzD()), old = d.mode[fid] || 'All approved services'; d.mode[fid] = val; fzLog(d, fid, 'Billing mode changed', { old, new: val }, reason); await fzSave(d); rerender(); }); };
FZ_ACT.frnSchForm = () => { if (!fzCan('Edit')) return; modal('Add fee item', `<div class="form-grid">${pcFld('Item', pcSel('sc_t', FZ_ITEMS, FZ_ITEMS[0]))}${pcFld('Basis', pcSel('sc_b', FZ_BASIS, FZ_BASIS[0]))}${pcFld('Amount (₹) or percent', '<input id="sc_r" type="number" min="0" step="0.01">')}${pcFld('Billed by', `<select id="sc_by"><option>MSEA</option><option value="3P">Third-party provider (bills the franchisee directly)</option></select>`)}${pcFld('Third-party name (if applicable)', '<input id="sc_n">')}</div>`, `<button class="btn primary" data-act="frnSchOk">Add</button><button class="btn" data-act="closeModal">Cancel</button>`); };
FZ_ACT.frnSchOk = async () => { const fid = App.ui.frnF, rate = +v('sc_r'), by = v('sc_by') === '3P' ? (v('sc_n') || '').trim() : 'MSEA', type = v('sc_t'), basis = v('sc_b'); if (!(rate > 0)) return toast('Enter the amount or percent.', 'bad'); if (basis === FZ_BASIS[1] && rate > 50) return toast('A percentage above 50 looks wrong.', 'bad'); if (v('sc_by') === '3P' && !by) return toast('Enter the third-party provider’s name.', 'bad'); const d = Store.clone(fzD()); d.sch[fid] = d.sch[fid] || []; if (d.sch[fid].some(s => s.type === type && s.active)) return toast('This item is already on the schedule.', 'bad'); d.sch[fid].push({ id: 'SC' + Date.now().toString(36), type, basis, rate, by, active: true }); fzLog(d, fid, `Fee item added: ${type}`, { new: `${basis} ${rate}, billed by ${by}` }, ''); await fzSave(d); closeModal(); };
FZ_ACT.frnGoFin = () => go('fn_ar');
const fzBillAmt = (d, fid, itemId, per) => { const s = (d.sch[fid] || []).find(x => x.id === itemId), ret = d.ret.find(r => r.fid === fid && r.period === per && r.state === 'Verified'); if (!s) return null; if (s.basis === FZ_BASIS[0]) return s.rate; if (!ret) return null; return s.basis === FZ_BASIS[1] ? Math.round(ret.feeColl * s.rate / 100) : Math.round(ret.students * s.rate); };
FZ_ACT.frnRaise = t => {
  const [iid, per] = t.dataset.k.split('|'), fid = App.ui.frnF, d = fzD(), f = d.fr.find(x => x.id === fid), s = (d.sch[fid] || []).find(x => x.id === iid), amt = fzBillAmt(d, fid, iid, per); if (!f || !s || amt == null) return; if (!can('fn_ar', 'Add')) return toast('You do not have permission to raise receivable invoices in Finance.', 'bad'); if (d.reg.some(r => r.fid === fid && r.period === per && r.item === iid)) return toast('This item is already invoiced for the month.', 'bad');
  const kind = { 'Franchise fee': 'Franchise fee', 'ERP / service fee': 'ERP / LMS service', 'Books and uniforms': 'Book distribution' }[s.type] || 'Other service'; FN_ACT.fnInvForm({ dataset: { c: f.cust } });
  const set = (id, val) => { const e = document.getElementById(id); if (e) e.value = val; }; set('iv_kind', kind); set('iv_gross', amt); set('iv_desc', `${s.type} for ${per} – ${f.name}`);
  toast('Finance invoice form opened with the amount filled in. After raising it, record the invoice number here.');
};
FZ_ACT.frnRegForm = t => { const [iid, per] = t.dataset.k.split('|'), d = fzD(), amt = fzBillAmt(d, App.ui.frnF, iid, per); modal('Record invoice number', `<p class="small">Amount expected: ${INR(amt)} (before GST). The invoice must exist in Finance for this franchisee.</p>${pcFld('Invoice number', '<input id="rg_n" placeholder="INV-…">')}`, `<button class="btn primary" data-act="frnRegOk" data-k="${t.dataset.k}">Save</button><button class="btn" data-act="closeModal">Cancel</button>`); };
FZ_ACT.frnRegOk = async t => {
  const [iid, per] = t.dataset.k.split('|'), fid = App.ui.frnF, d0 = fzD(), f = d0.fr.find(x => x.id === fid), no = (v('rg_n') || '').trim(), inv = (FT().invoices || []).find(i => i.no === no), amt = fzBillAmt(d0, fid, iid, per);
  if (!inv) return toast('No invoice with this number exists in Finance.', 'bad'); if (inv.customer !== f.cust) return toast('This invoice belongs to a different customer.', 'bad'); if (Math.abs((inv.gross || 0) - amt) > 1) return toast(`The invoice amount (${INR(inv.gross)}) differs from the schedule (${INR(amt)}).`, 'bad'); if (d0.reg.some(r => r.invNo === no)) return toast('This invoice is already recorded against another item.', 'bad'); if (d0.reg.some(r => r.fid === fid && r.period === per && r.item === iid)) return toast('This item is already invoiced for the month.', 'bad');
  const d = Store.clone(d0); d.reg.push({ fid, period: per, item: iid, invNo: no, amount: amt, by: App.user.name, at: nowIso() }); fzLog(d, fid, `Franchise invoice recorded: ${no}`, { new: `${per} ${INR(amt)}` }, ''); await fzSave(d); fzAud('Franchise invoice linked ' + no, { new: String(amt) }); closeModal();
};
